public static str ConstructAndGetJson(Object _class)
{
    ListEnumerator lEnum = new SysDictClass(classNum(TFMDrawFlowJsonCreator)).extendedBy().getEnumerator();
    TFMDrawFlowJsonCreator jsonCreator;
    while (lEnum.moveNext())
    {
        jsonCreator = new sysDictClass(lEnum.current()).makeObject();

        if (jsonCreator.classHandled() == classId2Name(classIdGet(_class)))
        {
            return jsonCreator.jSon(_class);
        }

    }
    return '';
}

public static TFMDrawFlowJsonCreator Construct(ClassName _className)
{
    ListEnumerator lEnum = new SysDictClass(classNum(TFMDrawFlowJsonCreator)).extendedBy().getEnumerator();
    TFMDrawFlowJsonCreator jsonCreator;
    while (lEnum.moveNext())
    {
        jsonCreator = new sysDictClass(lEnum.current()).makeObject();

        if (jsonCreator.classHandled() == _className)
        {
            return jsonCreator;
        }

    }
    return null;
}

